        "title": "リザードンの横必殺ワザを普段の移動にしない",
        "desc": "リザードンの横必殺ワザは強力な突進だが、自分にもダメージが入り、シールドされた後は隙を狙われる。普段は歩きやジャンプで間合いを調整し、横強攻撃などで安全に触れる距離を覚える。",
