        "desc": "空中前攻撃は前方に鉄球を出し、攻撃がしばらく続くため牽制に使いやすい。相手に密着しすぎず、ジャンプで近づいてくる相手へ鉄球を置く感覚を覚える。",
        "check": "トレモで相手との距離を変えながら小ジャンプの空中前攻撃を出し、鉄球を当てて着地する動きを10回中8回成功させる。"
