        "desc": "空中後攻撃はふっとばしが強く、撃墜を狙う主な手段になる。相手に背を向けて跳び、後方の鉄球を当てる練習から始める。",
        "check": "トレモで崖際の相手の蓄積ダメージを調整し、左右それぞれで空中後攻撃による撃墜を3回成功させる。"
